package dev.thefoolish.generated.anishelf;
import android.content.*;import android.widget.*;import java.util.*;
public final class MainActivity extends AppScreen{private LinearLayout results;private EditText query;protected void render(){title("Browse");subtitle("Search built-in reviewed providers immediately. Repository extensions can be added later.");query=new EditText(this);query.setHint("Search anime");query.setSingleLine(true);body.addView(query);Button s=button("Search providers");body.addView(s);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);body.addView(results);s.setOnClickListener(v->search());subtitle("Built in: "+BuiltInProviderCatalog.provenance());Button repos=button("Manage extension repositories");repos.setOnClickListener(v->AppNavigator.open(this,RepositoriesActivity.class));body.addView(repos);nav();showReady();}private void showReady(){results.removeAllViews();results.addView(text("A reviewed catalog provider is already installed. Search above, or add more providers from Extensions / Repositories.",13,false));}private void search(){results.removeAllViews();List<MediaProvider> providers=new ArrayList<>(BuiltInProviderCatalog.providers());for(ExtensionRecord x:new ExtensionManager(this).known())if(x.state==ExtensionRecord.State.ENABLED)providers.add(new RepositoryMediaProvider(x));if(providers.isEmpty()){results.addView(text("No compatible providers are available.",13,false));return;}for(MediaProvider p:providers){try{List<AnimeItem> found=p.search(query.getText().toString());for(AnimeItem a:found){Button b=button(a.title+(a.episodes>0?" · "+a.episodes+" episodes":""));b.setOnClickListener(v->{Intent i=new Intent(this,DetailActivity.class);i.putExtra("id",a.id);i.putExtra("title",a.title);i.putExtra("summary",a.summary);i.putExtra("provider",a.provider);i.putExtra("episodes",a.episodes);startActivity(i);});results.addView(b);}if(found.isEmpty())results.addView(text(p.displayName()+": no matches",13,false));}catch(Exception e){results.addView(text(p.displayName()+" failed: "+e.getMessage(),13,false));}}}}
